from PIL import Image, ImageOps
from pathlib import Path
import base64
from io import BytesIO

Path("build").mkdir(parents=True, exist_ok=True)

# Exact OPTIK LENTERA logo supplied by the owner (square master, 256px JPEG).
# Keep the complete artwork visible; do not crop, redraw, or zoom.
ORIGINAL_LOGO_JPEG = ""
source_image = Image.open(BytesIO(base64.b64decode(ORIGINAL_LOGO_JPEG))).convert("RGBA")
artwork = ImageOps.contain(source_image, (1024, 1024), method=Image.Resampling.LANCZOS)
canvas = Image.new("RGBA", (1024, 1024), (0, 0, 0, 0))
left = (1024 - artwork.width) // 2
top = (1024 - artwork.height) // 2
canvas.alpha_composite(artwork, (left, top))
canvas.save("build/optik_lentera_launcher.png", "PNG", optimize=True)
